import { AssumeRoleCommand, STSClient } from '@aws-sdk/client-sts';

/**
 * The static credentials returned by STS when assuming a customer role.
 */
export interface AssumedRoleCredentials {
    accessKeyId: string;
    secretAccessKey: string;
    sessionToken?: string;
    expiration?: Date;
}

export const DEFAULT_ASSUME_ROLE_SESSION_NAME = 'meteringco-scraper-validation';

export const defaultRegion = (): string =>
    process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

/**
 * Assume a customer supplied role, optionally with the external id the customer configured on the
 * trust relationship. The credentials returned here are the exact same credentials the collection
 * (scraping) microservices will use, which makes this a real proof that collection can work.
 */
export const assumeRole = async ({
    iamRoleArn,
    externalId,
    sessionName = DEFAULT_ASSUME_ROLE_SESSION_NAME,
    region = defaultRegion(),
}: {
    iamRoleArn: string;
    externalId?: string;
    sessionName?: string;
    region?: string;
}): Promise<AssumedRoleCredentials> => {
    const stsClient = new STSClient({ region });
    const { Credentials } = await stsClient.send(
        new AssumeRoleCommand({
            RoleArn: iamRoleArn,
            RoleSessionName: sessionName,
            ExternalId: externalId ? externalId : undefined,
        }),
    );
    if (!Credentials?.AccessKeyId || !Credentials?.SecretAccessKey) {
        throw new Error('STS did not return credentials for the supplied role');
    }
    return {
        accessKeyId: Credentials.AccessKeyId,
        secretAccessKey: Credentials.SecretAccessKey,
        sessionToken: Credentials.SessionToken,
        expiration: Credentials.Expiration,
    };
};
