import { BadRequestException, Logger } from '@nestjs/common';
import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { serializeError } from 'serialize-error';

import { getInstanceWithFilters } from '../../utils/aws/awsEc2.js';
import { assumeRole, AssumedRoleCredentials, defaultRegion } from '../../utils/aws/awsSts.js';

/**
 * The shape of the cloud IAM (scraper role) settings block, kept structural on purpose so this
 * module can be used by both the DTO validation layer and the service layer without introducing
 * import cycles.
 */
export interface CloudIAMLike {
    iamRoleArn?: string;
    externalId?: string;
}

export const cloudIAMValidationMessages = {
    missingRole:
        'cloudIAM.iamRoleArn must be supplied. Send an empty iamRoleArn to disconnect the IAM role for this business.',
    invalidBlock:
        'cloudIAM must be an object containing an iamRoleArn. Send an empty iamRoleArn to disconnect the IAM role for this business.',
    notAssumable: (iamRoleArn: string) =>
        `Unable to assume the IAM role ${iamRoleArn} with the external id supplied. Double check the role ARN, the external id and the trust relationship of the role.`,
    noInventoryAccess: (iamRoleArn: string) =>
        `The IAM role ${iamRoleArn} was assumed but the credentials returned cannot describe EC2 instances. Grant the role ec2:DescribeInstances so usage collection can read the instance inventory.`,
};

/**
 * Thrown when a customer supplied scraper role cannot be validated.
 *
 * The response body keeps the same shape as the validation pipe (a list of messages) while the
 * exception message itself stays human readable for logs and unit tests.
 */
export class CloudIAMValidationException extends BadRequestException {
    constructor(messages: string | string[]) {
        const messageList = Array.isArray(messages) ? messages : [messages];
        super({ statusCode: 400, message: messageList, error: 'Bad Request' });
        this.message = messageList.join(' ');
    }
}

const logger = new Logger('CloudIAMValidation');

/**
 * True when the supplied role is blank, meaning the customer wants to disconnect their AWS account.
 */
export const isDisconnectRequest = (cloudIAM: CloudIAMLike): boolean =>
    typeof cloudIAM?.iamRoleArn === 'string' && cloudIAM.iamRoleArn.trim() === '';

/**
 * Verifies that the supplied role can be assumed with the supplied external id and that the
 * credentials handed back are able to read the EC2 instance inventory used by usage collection.
 *
 * @throws CloudIAMValidationException when either check fails.
 */
export const verifyCloudIAMAccess = async ({ iamRoleArn, externalId }: CloudIAMLike): Promise<void> => {
    let credentials: AssumedRoleCredentials;
    try {
        credentials = await assumeRole({ iamRoleArn, externalId });
    } catch (error) {
        logger.error(
            `Failed to assume role ${iamRoleArn} while validating cloud IAM settings: ${JSON.stringify(
                serializeError(error),
            )}`,
        );
        throw new CloudIAMValidationException(cloudIAMValidationMessages.notAssumable(iamRoleArn));
    }
    try {
        // Exercise the exact read the collection microservices perform with these credentials.
        await getInstanceWithFilters(defaultRegion(), credentials);
    } catch (error) {
        logger.error(
            `Assumed role ${iamRoleArn} cannot read the instance inventory: ${JSON.stringify(serializeError(error))}`,
        );
        throw new CloudIAMValidationException(cloudIAMValidationMessages.noInventoryAccess(iamRoleArn));
    }
};

/**
 * Validates and normalises the cloudIAM block of a settings update.
 *
 * - `undefined` means the block was not part of the request, nothing to do.
 * - A blank `iamRoleArn` is a disconnect request, the external id is cleared alongside the role.
 * - A block that does not name a role at all is a bad request, it is not treated as a disconnect.
 * - Anything else must be proven to be assumable and able to read the instance inventory.
 *
 * @returns the cloudIAM block that should be persisted.
 * @throws CloudIAMValidationException when the block is invalid or the role cannot be used.
 */
export const validateCloudIAMSettings = async (cloudIAM: CloudIAMLike): Promise<CloudIAMLike> => {
    if (cloudIAM === undefined) {
        return undefined;
    }
    if (cloudIAM === null || typeof cloudIAM !== 'object' || Array.isArray(cloudIAM)) {
        throw new CloudIAMValidationException(cloudIAMValidationMessages.invalidBlock);
    }
    const { iamRoleArn, externalId } = cloudIAM;
    if (typeof iamRoleArn !== 'string') {
        throw new CloudIAMValidationException(cloudIAMValidationMessages.missingRole);
    }
    if (isDisconnectRequest(cloudIAM)) {
        // Disconnecting, the external id is meaningless without a role so it is cleared as well.
        return { iamRoleArn: '', externalId: '' };
    }
    const trimmedRole = iamRoleArn.trim();
    await verifyCloudIAMAccess({ iamRoleArn: trimmedRole, externalId });
    return externalId ? { iamRoleArn: trimmedRole, externalId } : { iamRoleArn: trimmedRole };
};

const cloudIAMValidationError = Symbol('cloudIAMValidationError');

@ValidatorConstraint({ name: 'ValidCloudIAMRule', async: true })
export class ValidCloudIAMRule implements ValidatorConstraintInterface {
    async validate(cloudIAM: CloudIAMLike, args: ValidationArguments) {
        try {
            await validateCloudIAMSettings(cloudIAM);
            return true;
        } catch (error) {
            if (args?.object) {
                Object.defineProperty(args.object, cloudIAMValidationError, {
                    value: error?.message,
                    enumerable: false,
                    configurable: true,
                    writable: true,
                });
            }
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        return args?.object?.[cloudIAMValidationError] ?? cloudIAMValidationMessages.invalidBlock;
    }
}

export function ValidCloudIAM(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidCloudIAM',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [],
            options: validationOptions,
            validator: ValidCloudIAMRule,
        });
    };
}
