import { IAMClient, CreateRoleCommand, PutRolePolicyCommand } from '@aws-sdk/client-iam';
import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import { BadRequestException } from '@nestjs/common';

import { SettingsService } from './settings.service.js';
import { InfluxService } from '../influx/influx.service.js';
import { UpdateSettingsDto } from './dto/update-settings.dto.js';
import { validateCloudIAMSettings } from './dto/cloudIAMAuthorizer.js';

const ACCOUNT = '600000000042';
const iam = new IAMClient({});
const trust = (ext?: string) =>
    JSON.stringify({
        Version: '2012-10-17',
        Statement: [
            {
                Effect: 'Allow',
                Principal: { AWS: `arn:aws:iam::${ACCOUNT}:root` },
                Action: 'sts:AssumeRole',
                ...(ext ? { Condition: { StringEquals: { 'sts:ExternalId': ext } } } : {}),
            },
        ],
    });

const makeRole = async (name: string, ext: string | undefined, policy: unknown) => {
    try {
        await iam.send(new CreateRoleCommand({ RoleName: name, AssumeRolePolicyDocument: trust(ext) }));
    } catch (e) {
        /* already there */
    }
    if (policy) {
        await iam.send(
            new PutRolePolicyCommand({ RoleName: name, PolicyName: 'p', PolicyDocument: JSON.stringify(policy) }),
        );
    }
    return `arn:aws:iam::${ACCOUNT}:role/${name}`;
};

const allowEc2 = { Version: '2012-10-17', Statement: [{ Effect: 'Allow', Action: ['ec2:Describe*'], Resource: '*' }] };
const denyEc2 = {
    Version: '2012-10-17',
    Statement: [{ Effect: 'Deny', Action: ['ec2:DescribeInstances'], Resource: '*' }],
};

describe('cloud IAM scraper role validation', () => {
    let service: SettingsService;
    let influxService: InfluxService;
    let goodRole: string;
    let noEc2Role: string;
    let noExternalIdRole: string;

    beforeAll(async () => {
        goodRole = await makeRole('scratch-good', 'secret123', allowEc2);
        noEc2Role = await makeRole('scratch-noec2', 'secret123', denyEc2);
        noExternalIdRole = await makeRole('scratch-noext', undefined, allowEc2);
    });

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
            .useMocker(createMock)
            .compile();
        service = module.get(SettingsService);
        influxService = module.get(InfluxService);
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([]);
    });
    afterEach(() => jest.clearAllMocks());

    it('saves a role that can be assumed and can read the inventory', async () => {
        const res = await service.update({
            businessID: 'b1',
            cloudIAM: { iamRoleArn: goodRole, externalId: 'secret123' },
        } as UpdateSettingsDto);
        expect(res.data[0].cloudIAM).toEqual({ iamRoleArn: goodRole, externalId: 'secret123' });
        expect(influxService.loadPoints).toHaveBeenCalled();
    });

    it('rejects a role that cannot be assumed and writes nothing', async () => {
        await expect(
            service.update({ businessID: 'b1', cloudIAM: { iamRoleArn: 'wow a fake role' } } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('rejects when the external id does not match', async () => {
        await expect(
            service.update({
                businessID: 'b1',
                cloudIAM: { iamRoleArn: goodRole, externalId: 'nope' },
            } as UpdateSettingsDto),
        ).rejects.toThrow(/IAM/);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('rejects when the external id is missing but required', async () => {
        await expect(
            service.update({ businessID: 'b1', cloudIAM: { iamRoleArn: goodRole } } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);
    });

    it('rejects a role without ec2 describe instances and writes nothing', async () => {
        await expect(
            service.update({
                businessID: 'b1',
                cloudIAM: { iamRoleArn: noEc2Role, externalId: 'secret123' },
            } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('does not write any other field of a failing save', async () => {
        await expect(
            service.update({
                businessID: 'b1',
                businessName: 'should not be saved',
                cloudIAM: { iamRoleArn: noEc2Role, externalId: 'secret123' },
            } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('accepts a role with no external id required', async () => {
        const res = await service.update({
            businessID: 'b1',
            cloudIAM: { iamRoleArn: noExternalIdRole },
        } as UpdateSettingsDto);
        expect(res.data[0].cloudIAM.iamRoleArn).toEqual(noExternalIdRole);
    });

    it('treats a blank role as a disconnect and clears the external id', async () => {
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([
            { _value: 'biz', businessID: 'b1', cloudIAM: JSON.stringify({ iamRoleArn: goodRole, externalId: 'secret123' }) },
        ] as never);
        const res = await service.update({ businessID: 'b1', cloudIAM: { iamRoleArn: '' } } as UpdateSettingsDto);
        expect(res.data[0].cloudIAM.iamRoleArn).toEqual('');
        expect(res.data[0].cloudIAM.externalId).toBeFalsy();
        expect(influxService.loadPoints).toHaveBeenCalled();
    });

    it('clears the external id even when one is supplied with a blank role', async () => {
        const res = await service.update({
            businessID: 'b1',
            cloudIAM: { iamRoleArn: '', externalId: 'secret123' },
        } as UpdateSettingsDto);
        expect(res.data[0].cloudIAM.externalId).toBeFalsy();
    });

    it('rejects a cloudIAM block that names no role', async () => {
        await expect(service.update({ businessID: 'b1', cloudIAM: {} } as UpdateSettingsDto)).rejects.toThrow(
            BadRequestException,
        );
        await expect(
            service.update({ businessID: 'b1', cloudIAM: { externalId: 'secret123' } } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('leaves saves without a cloudIAM block alone', async () => {
        const res = await service.update({ businessID: 'b1', businessName: 'name' } as UpdateSettingsDto);
        expect(res.data[0].businessName).toEqual('name');
        expect(influxService.loadPoints).toHaveBeenCalled();
    });

    it('reports failures through DTO validation as a 400 style message list', async () => {
        const dto = plainToInstance(UpdateSettingsDto, { cloudIAM: { iamRoleArn: 'wow a fake role', externalId: 'x' } });
        const errors = await validate(dto);
        expect(errors.length).toBeGreaterThan(0);
        expect(Object.values(errors[0].constraints)[0]).toEqual(expect.stringContaining('IAM'));

        const emptyDto = plainToInstance(UpdateSettingsDto, { cloudIAM: {} });
        const emptyErrors = await validate(emptyDto);
        expect(emptyErrors.length).toBeGreaterThan(0);

        const okDto = plainToInstance(UpdateSettingsDto, { cloudIAM: { iamRoleArn: goodRole, externalId: 'secret123' } });
        expect(await validate(okDto)).toEqual([]);
    });

    it('exposes the validation helper', async () => {
        await expect(validateCloudIAMSettings({ iamRoleArn: goodRole, externalId: 'secret123' })).resolves.toEqual({
            iamRoleArn: goodRole,
            externalId: 'secret123',
        });
        await expect(validateCloudIAMSettings(undefined)).resolves.toBeUndefined();
    });
});
