import { ValidationPipe } from '@nestjs/common';
import { UpdateSettingsDto } from './dto/update-settings.dto.js';

const pipe = new ValidationPipe({ whitelist: true, transform: true });
const run = async (body: unknown) => {
    try {
        const out = await pipe.transform(body as never, { type: 'body', metatype: UpdateSettingsDto } as never);
        return { ok: true, out };
    } catch (e) {
        return { ok: false, status: e.getStatus(), body: e.getResponse() };
    }
};

describe('validation pipe behaviour for cloudIAM', () => {
    it('fake role -> 400 with IAM message', async () => {
        const res = await run({ cloudIAM: { iamRoleArn: 'wow a fake role', externalId: 'foobar' } });
        console.log(JSON.stringify(res));
        expect(res.ok).toBe(false);
        expect(res.status).toEqual(400);
        expect(res.body.message[0]).toEqual(expect.stringContaining('IAM'));
    });
    it('no role named -> 400 with IAM message', async () => {
        const res = await run({ cloudIAM: { externalId: 'foobar' } });
        console.log(JSON.stringify(res));
        expect(res.ok).toBe(false);
        expect(res.body.message[0]).toEqual(expect.stringContaining('IAM'));
    });
    it('empty block -> 400', async () => {
        const res = await run({ cloudIAM: {} });
        console.log(JSON.stringify(res));
        expect(res.ok).toBe(false);
