import { BadRequestException } from '@nestjs/common';
import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { CreateRoleCommand, IAMClient, PutRolePolicyCommand } from '@aws-sdk/client-iam';
import { GetCallerIdentityCommand, STSClient } from '@aws-sdk/client-sts';

import { SettingsService } from './settings.service.js';
import { InfluxService } from '../influx/influx.service.js';
import { UpdateSettingsDto } from './dto/update-settings.dto.js';
import { validateCloudIAMSettings } from './dto/cloudIAMAuthorizer.js';

const EXTERNAL_ID = 'cloud-iam-spec-external-id';
const iamClient = new IAMClient({});

const trustPolicy = (accountId: string, externalId?: string) =>
    JSON.stringify({
        Version: '2012-10-17',
        Statement: [
            {
                Effect: 'Allow',
                Principal: { AWS: `arn:aws:iam::${accountId}:root` },
                Action: 'sts:AssumeRole',
                ...(externalId ? { Condition: { StringEquals: { 'sts:ExternalId': externalId } } } : {}),
            },
        ],
    });

const createRole = async ({
    accountId,
    roleName,
    externalId,
    policyDocument,
}: {
    accountId: string;
    roleName: string;
    externalId?: string;
    policyDocument?: unknown;
}): Promise<string> => {
    try {
        await iamClient.send(
            new CreateRoleCommand({ RoleName: roleName, AssumeRolePolicyDocument: trustPolicy(accountId, externalId) }),
        );
    } catch (error) {
        // The role already exists from a previous run of the suite.
    }
    if (policyDocument) {
        await iamClient.send(
            new PutRolePolicyCommand({
                RoleName: roleName,
                PolicyName: 'cloud-iam-spec-policy',
                PolicyDocument: JSON.stringify(policyDocument),
            }),
        );
    }
    return `arn:aws:iam::${accountId}:role/${roleName}`;
};

const readInventoryPolicy = {
    Version: '2012-10-17',
    Statement: [{ Effect: 'Allow', Action: ['ec2:Describe*'], Resource: '*' }],
};
const noInventoryPolicy = {
    Version: '2012-10-17',
    Statement: [{ Effect: 'Deny', Action: ['ec2:DescribeInstances'], Resource: '*' }],
};

describe('cloudIAM scraper role validation on settings update', () => {
    let service: SettingsService;
    let influxService: InfluxService;
    let assumableRole: string;
    let roleWithoutInventoryAccess: string;

    beforeAll(async () => {
        const { Account } = await new STSClient({}).send(new GetCallerIdentityCommand({}));
        assumableRole = await createRole({
            accountId: Account,
            roleName: 'cloud-iam-spec-scraper',
            externalId: EXTERNAL_ID,
            policyDocument: readInventoryPolicy,
        });
        roleWithoutInventoryAccess = await createRole({
            accountId: Account,
            roleName: 'cloud-iam-spec-scraper-no-inventory',
            externalId: EXTERNAL_ID,
            policyDocument: noInventoryPolicy,
        });
    });

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
            .useMocker(createMock)
            .compile();
        service = module.get(SettingsService);
        influxService = module.get(InfluxService);
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([]);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('saves a role that can be assumed with the external id and can read the instance inventory', async () => {
        const { data } = await service.update({
            businessID: 'some-business-id',
            cloudIAM: { iamRoleArn: assumableRole, externalId: EXTERNAL_ID },
        } as UpdateSettingsDto);

        expect(data[0].cloudIAM).toEqual({ iamRoleArn: assumableRole, externalId: EXTERNAL_ID });
        expect(influxService.loadPoints).toHaveBeenCalled();
    });

    it('rejects a role that cannot be assumed and writes nothing at all', async () => {
        await expect(
            service.update({
                businessID: 'some-business-id',
                businessName: 'should not be persisted',
                cloudIAM: { iamRoleArn: 'not a role at all' },
            } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);

        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('rejects a role when the external id does not match the trust relationship', async () => {
        await expect(
            service.update({
                businessID: 'some-business-id',
                cloudIAM: { iamRoleArn: assumableRole, externalId: 'the-wrong-external-id' },
            } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);

        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('rejects a role whose credentials cannot read the instance inventory and writes nothing at all', async () => {
        await expect(
            service.update({
                businessID: 'some-business-id',
                businessName: 'should not be persisted',
                cloudIAM: { iamRoleArn: roleWithoutInventoryAccess, externalId: EXTERNAL_ID },
            } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);

        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('treats a blank role as a disconnect and clears the external id', async () => {
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([
            {
                _value: 'some business',
                businessID: 'some-business-id',
                cloudIAM: JSON.stringify({ iamRoleArn: assumableRole, externalId: EXTERNAL_ID }),
            },
        ] as never);

        const { data } = await service.update({
            businessID: 'some-business-id',
            cloudIAM: { iamRoleArn: '', externalId: EXTERNAL_ID },
        } as UpdateSettingsDto);

        expect(data[0].cloudIAM.iamRoleArn).toEqual('');
        expect(data[0].cloudIAM.externalId).toBeFalsy();
        expect(influxService.loadPoints).toHaveBeenCalled();
    });

    it('rejects a cloudIAM block that names no role instead of treating it as a disconnect', async () => {
        await expect(
            service.update({ businessID: 'some-business-id', cloudIAM: {} } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);
        await expect(
            service.update({
                businessID: 'some-business-id',
                cloudIAM: { externalId: EXTERNAL_ID },
            } as UpdateSettingsDto),
        ).rejects.toThrow(BadRequestException);

        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('does not touch the cloudIAM settings of updates that do not contain a cloudIAM block', async () => {
        const { data } = await service.update({
            businessID: 'some-business-id',
            businessName: 'a new name',
        } as UpdateSettingsDto);

        expect(data[0].businessName).toEqual('a new name');
        expect(influxService.loadPoints).toHaveBeenCalled();
    });

    it('normalises the cloudIAM block that gets persisted', async () => {
        await expect(
            validateCloudIAMSettings({ iamRoleArn: assumableRole, externalId: EXTERNAL_ID }),
        ).resolves.toEqual({
            iamRoleArn: assumableRole,
            externalId: EXTERNAL_ID,
        });
        await expect(validateCloudIAMSettings({ iamRoleArn: '  ' })).resolves.toEqual({ iamRoleArn: '' });
        await expect(validateCloudIAMSettings(undefined)).resolves.toBeUndefined();
    });
});
EOF
